namespace FoodExpiryApp; public class SupportPage:ContentPage { public SupportPage(){Title="Поддержка";BackgroundColor=Color.FromArgb("#111116");var s=new VerticalStackLayout{Padding=22,Spacing=14};s.Children.Add(new Label{Text="☕ Поддержать разработчика",FontSize=26,TextColor=Colors.White,FontAttributes=FontAttributes.Bold});s.Children.Add(new Label{Text="Спасибо, что помогаешь развивать FoodExpiryApp ❤️",TextColor=Color.FromArgb("#B7B2C1")});Add(s,"☕ На чашку кофе — 70 ₽");Add(s,"🍪 Пачку печенек — 120 ₽");Add(s,"👑 Золотые печеньки — 500 ₽");s.Children.Add(new Label{Text="Оплата пока не подключена. Для реальных пожертвований потребуется платёжный сервис или официальная ссылка.",TextColor=Color.FromArgb("#FFB65C")});Content=new ScrollView{Content=s};}static void Add(VerticalStackLayout s,string text){var b=new Button{Text=text,BackgroundColor=Color.FromArgb("#282431"),TextColor=Colors.White,HeightRequest=56};b.Clicked+=async(_,_)=>await Application.Current!.Windows[0].Page!.DisplayAlert("Поддержка","Интерфейс готов, реальная оплата пока не подключена.","ОК");s.Children.Add(b);} }
